<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\Gateway;

use Override;
use ArrayIterator;
use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\UserMfaRecoveryCode;
use Civi\Lughauth\Shared\Value\Pagination\Slider;

/**
 * @template-extends ArrayIterator<int, UserMfaRecoveryCode>
 */
class UserMfaRecoveryCodeSlide extends \ArrayIterator
{
    private readonly ?UserMfaRecoveryCode $last;
    private readonly UserMfaRecoveryCodeCursor $nextCursor;
    public function __construct(
        private readonly ?\Closure $next,
        private readonly ?UserMfaRecoveryCodeCursor $cursor,
        private readonly array $values,
        private readonly bool $hasNext = false,
        private readonly int $lookahead = 0
    ) {
        parent::__construct($values);
        $this->last = $values ? end($values) : null;
        $cursor = $this->cursor ?? new UserMfaRecoveryCodeCursor(limit: 1000);
        $this->nextCursor = null === $this->last ? $cursor : $cursor->next($this->last, null);
    }
    public function cursor(): ?UserMfaRecoveryCodeCursor
    {
        return $this->cursor;
    }
    public function nextCursor(): UserMfaRecoveryCodeCursor
    {
        return $this->nextCursor;
    }
    public function hasNext(): bool
    {
        return $this->hasNext;
    }
    public function values(): array
    {
        return $this->values;
    }
    #[Override]
    public function current(): ?UserMfaRecoveryCode
    {
        return parent::current();
    }
    public function map(\Closure $fn): UserMfaRecoveryCodeSlide
    {
        return new UserMfaRecoveryCodeSlide($this->next, $this->cursor, array_map($fn, $this->values), $this->hasNext, $this->lookahead);
    }
    public function slide(\Closure $fn): UserMfaRecoveryCodeSlide
    {
        $cursor = $this->cursor;
        $next = $this->next;
        if (null === $cursor || null === $next) {
            return new UserMfaRecoveryCodeSlide($next, $cursor, array_values(array_filter($this->values, $fn)));
        }
        $page = Slider::slide(
            $this->values,
            $cursor->limit() + $this->lookahead,
            $cursor->limit(),
            fn (UserMfaRecoveryCode $after, int $size): array => $next($this, $cursor->next($after, $size))->values(),
            $fn,
        );
        return new UserMfaRecoveryCodeSlide($next, $cursor, $page->items, $page->hasNext);
    }
}
